    H,W=len(g),len(g[0])
    bgc=Counter(x for row in g for x in row).most_common(1)[0][0]
    seen=[[False]*W for _ in range(H)]; out=[[bgc]*W for _ in range(H)]
    for i in range(H):
        for j in range(W):
            if g[i][j]!=bgc and not seen[i][j]:
                st=[(i,j)]; seen[i][j]=True; pts=[]
                while st:
                    a,b=st.pop(); pts.append((a,b))
                    for da,db in ((1,0),(-1,0),(0,1),(0,-1)):
                        na,nb=a+da,b+db
                        if 0<=na<H and 0<=nb<W and not seen[na][nb] and g[na][nb]==g[i][j]:
                            seen[na][nb]=True; st.append((na,nb))
                rs={p[0] for p in pts}; cs_={p[1] for p in pts}
                if len(pts)!=len(rs)*len(cs_) or max(rs)-min(rs)<2 or max(cs_)-min(cs_)<2: continue
                r0,r1,l0,l1=min(rs),max(rs),min(cs_),max(cs_)
                for i in range(r0,r1+1):
                    for j in range(l0,l1+1):
                        dd=min(i-r0,r1-i,j-l0,l1-j)
                        corner=(dd==0 and i in(r0,r1) and j in(l0,l1))
                        out[i][j]= 1 if corner else (4 if dd==0 else 2)
    return out
